INSERT INTO `ProductReview` (`itemSlug`, `rating`, `authorName`, `location`, `reviewText`, `sortOrder`, `createdAt`) VALUES
('premium-special-varkey', '5', 'Ananya Nair', 'Ernakulam, Kerala', 'You can immediately taste the difference with this Premium Special Varkey. The layers are unbelievably rich, flaky, and melt in your mouth the second you dip them in hot chai. Worth every rupee for anyone who appreciates top-tier bakery quality.', 1, NOW(3)),
('premium-special-varkey', '4.8', 'Vikramaditya Rao', 'Bengaluru Urban, Karnataka', 'I bought this pack for guests, and everyone asked where I ordered it from! It has a rich, buttery aroma and an ultra-crisp bite that feels truly gourmet. Easily the best Varkey I have ever had outside of Ooty.', 2, NOW(3)),
('premium-special-varkey', '5', 'Meera Deshmukh', 'Pune, Maharashtra', 'The craftsmanship in every piece is obvious from the first crunch. Unlike regular rusks that feel hard, these have delicate, airy layers that hold together well without feeling heavy or oily. Definitely keeping a box stocked for special occasions.', 3, NOW(3)),
('premium-special-varkey', '4.7', 'Karthik Subramanian', 'Coimbatore, Tamil Nadu', 'If you love authentic Nilgiri baked goods, this premium variant is an absolute treat. The balance of subtle sweetness and rich flavor pairs wonderfully with black coffee or masala tea. Packaging kept every single piece completely intact.', 4, NOW(3)),
('premium-special-varkey', '4.4', 'Siddharth Malhotra', 'South Delhi, Delhi', 'Ordered two packs after trying a friend''s batch, and they did not disappoint. Fresh out of the box, the texture is crisp and golden-baked to perfection. It elevates a simple evening tea break into something really special.', 5, NOW(3)),
('premium-special-varkey', '5', 'Priyanka Chatterjee', 'Kolkata, West Bengal', 'Hands down the finest Varkey available online. There is zero oiliness, just pure, clean flavor and dozens of crisp, flaky layers in every bite. Once you try the Premium Special, it’s hard to go back to anything else.', 6, NOW(3)),
('special-varkey', '4.9', 'Rohan Kulkarni', 'Mumbai Suburban, Maharashtra', 'This Special Varkey hits the sweet spot between everyday comfort and bakery-style richness. It’s crisp, light, and holds up well when dipped into piping hot filter coffee. Our whole family finishes a packet in just two days!', 1, NOW(3)),
('special-varkey', '4.6', 'Divya Krishnan', 'Thrissur, Kerala', 'Really impressed by the freshness and texture of this batch. Every piece has that signature puff-pastry crunch without being overly sweet or greasy. A fantastic upgrade from standard tea-time snacks.', 2, NOW(3)),
('special-varkey', '4.2', 'Harish Reddy', 'Hyderabad, Telangana', 'I always look for snacks that aren''t loaded with sugar, and this Special Varkey is just right. The golden crust gives a satisfying crunch, while the inside stays airy and light. Will definitely be reordering soon.', 3, NOW(3)),
('special-varkey', '5', 'Nandini Iyer', 'Chennai, Tamil Nadu', 'Brought back instant memories of hill-station bakeries! The flavor is rich and comforting, and the biscuit doesn''t crumble to dust the second it touches warm milk or tea. Great value for the quality you get.', 4, NOW(3)),
('special-varkey', '4.5', 'Abhishek Sharma', 'Jaipur, Rajasthan', 'Super fresh and neatly packed so nothing arrived broken. The layers are crisp and evenly baked, giving you that classic South Indian bakery taste right at home. My parents especially love having this with their morning tea.', 5, NOW(3)),
('special-varkey', '4.8', 'Sneha Hegde', 'Dakshina Kannada, Karnataka', 'A staple in our kitchen jar now. It has a wonderful roasted aroma and just enough richness to make it feel special without feeling heavy on the stomach. Highly recommended for daily tea lovers.', 6, NOW(3)),
('regular-varkey', '5', 'Aravind Menon', 'Kozhikode, Kerala', 'Pure nostalgia in every single bite! This Classic Ooty Varkey tastes exactly like the ones we used to pick up fresh from local bakeries in the Nilgiris. Light, crunchy, and mildly sweet—it’s the ultimate chai companion.', 1, NOW(3)),
('regular-varkey', '5', 'Lakshmi Narayanan', 'The Nilgiris, Tamil Nadu', 'Nothing beats the original, and this recipe nails the authentic Ooty texture. It’s firm enough for a proper dip in hot tea yet flaky enough to crumble effortlessly in your mouth. Truly tastes homemade and fresh.', 2, NOW(3)),
('regular-varkey', '4.3', 'Pranav Joshi', 'Ahmedabad, Gujarat', 'I’ve tried many brands claiming to sell authentic Ooty Varkey, and this is by far the closest to the real deal. No artificial aftertaste, no excess oil—just simple, honest ingredients baked to a crisp golden finish.', 3, NOW(3)),
('regular-varkey', '4.7', 'Shruti Bhat', 'Mysuru, Karnataka', 'My evening tea feels incomplete without two pieces of this classic Varkey. It has that distinct, comforting aroma and a clean, subtle sweetness that never gets boring. Always arrives super fresh.', 4, NOW(3)),
('regular-varkey', '4.9', 'Senthil Kumar', 'Madurai, Tamil Nadu', 'Sent a pack to my parents who lived in Coimbatore for years, and they were thrilled with the authenticity. The layers are well-defined and crunchy without being rock-hard on the teeth. A timeless classic done right.', 5, NOW(3)),
('regular-varkey', '4.5', 'Ritika Verma', 'Lucknow, Uttar Pradesh', 'Simple, traditional, and utterly addictive. Whether you eat it plain as a midday snack or dunk it in ginger chai, the texture stays wonderfully crisp. You can tell it''s baked in small, fresh batches.', 6, NOW(3)),
('crispy-varkey', '4.8', 'Nikhil Choudhury', 'Kamrup Metropolitan, Assam', 'If you live for that loud, satisfying crunch, this Crispy Varkey is made for you! Every layer is baked to perfection, giving you a light, snappy bite from start to finish. It stays crunchy even after opening the pack.', 1, NOW(3)),
('crispy-varkey', '4.4', 'Deepak Pillai', 'Thiruvananthapuram, Kerala', 'I prefer my tea biscuits extra crisp rather than soft, and this hit the mark completely. It doesn''t turn soggy too fast when dipped in hot tea, keeping a nice bite right to the last piece. Easily my new favorite.', 2, NOW(3)),
('crispy-varkey', '5', 'Pooja Agarwal', 'Indore, Madhya Pradesh', 'The texture on these is unreal—airy, brittle in the best way, and completely free of any greasy residue. You can easily snack on three or four pieces without feeling weighed down. Great for crunch lovers!', 3, NOW(3)),
('crispy-varkey', '4.6', 'Naveen Gowda', 'Hassan, Karnataka', 'Super light and wonderfully crisp! Even my kids, who usually skip traditional bakery items, couldn''t stop munching on these straight out of the jar. Love how fresh and snappy every piece is.', 4, NOW(3)),
('crispy-varkey', '4.7', 'Swathi Venkatesh', 'Salem, Tamil Nadu', 'Baked to a gorgeous golden brown with an unbeatable crunch. It has a lovely toasted flavor that pairs especially well with strong black tea or espresso. Arrived intact with barely any crumbs at the bottom.', 5, NOW(3)),
('crispy-varkey', '4', 'Manish Tiwari', 'Chandigarh, Chandigarh', 'Finally, a Varkey that doesn''t feel dense or chewy! The extra crispness makes every layer pop as you bite into it. Keep it in an airtight jar and it stays fresh for weeks.', 6, NOW(3)),
('mini-varkey', '5', 'Aishwarya Shenoy', 'Udupi, Karnataka', 'These bite-sized Mini Varkeys are dangerously addictive! They give you all the flaky, buttery goodness of a full-sized Varkey in a neat, pop-in-your-mouth size. Zero mess and zero crumbs everywhere.', 1, NOW(3)),
('mini-varkey', '4.7', 'Gautam Sethi', 'Gurugram, Haryana', 'Such a smart idea for portion control and quick snacking. I keep a jar on my work desk for afternoon coffee breaks, and one or two little pieces satisfy my craving without needing a full snack. Super crisp and fresh!', 2, NOW(3)),
('mini-varkey', '4.3', 'Kavitha Rajendran', 'Tiruchirappalli, Tamil Nadu', 'Kids absolutely love these mini versions! They fit right into school snack boxes and don''t break into messy pieces while eating. Same authentic Ooty flavor, just made way more convenient.', 3, NOW(3)),
('mini-varkey', '4.8', 'Sandeep Patnaik', 'Khordha, Odisha', 'Great for serving guests alongside tea or coffee! Everyone can easily pick up a piece or two without having to break a large biscuit in half. Light, crunchy, and baked to golden perfection.', 4, NOW(3)),
('mini-varkey', '4.5', 'Roshni Varghese', 'Kottayam, Kerala', 'I didn''t expect the mini size to still have so many flaky layers, but the texture is spot on. Every bite is crisp, airy, and mildly sweet. A packet disappears way faster than I''d like to admit!', 5, NOW(3)),
('mini-varkey', '4.9', 'Varun Naidu', 'Visakhapatnam, Andhra Pradesh', 'Perfect travel snack! I carried a pack on a road trip recently, and having bite-sized pieces made munching in the car completely hassle-free. Fresh, crunchy, and delicious.', 6, NOW(3)),
('varkey-flakes', '4.9', 'Tanvi Gokhale', 'Nagpur, Maharashtra', 'Who knew Varkey Flakes could be this addictive? They have the exact crisp, buttery taste of fresh Varkey in light, crunchy shards that you can eat by the handful. It’s like the best part of the puff pastry!', 1, NOW(3)),
('varkey-flakes', '5', 'Ashwin Sundaram', 'Erode, Tamil Nadu', 'I love using these as a crunchy topping over vanilla ice cream or kheer—they add an incredible bakery-style texture! Of course, they are just as amazing eaten straight from the bowl with a cup of hot tea.', 2, NOW(3)),
('varkey-flakes', '4.2', 'Neha Kapoor', 'Gautam Buddha Nagar, Uttar Pradesh', 'Light as air and packed with crunch! Whenever I want a quick savory-sweet nibble without committing to a heavy snack, a small bowl of Varkey Flakes hits the spot. Super fresh and zero oiliness.', 3, NOW(3)),
('varkey-flakes', '4.6', 'Chetan Shetty', 'Belagavi, Karnataka', 'Such a fun and unique snack! Every flake is golden, crisp, and melts right on your tongue. My family fights over the jar during movie nights because you just can''t stop munching on them.', 4, NOW(3)),
('varkey-flakes', '4.8', 'Anjali Kurian', 'Palakkad, Kerala', 'A brilliant way to enjoy the classic Varkey flavor in a lighter, crisper form. They stay wonderfully crunchy in an airtight container and pair brilliantly with evening masala chai. Definitely ordering more.', 5, NOW(3)),
('varkey-flakes', '4.5', 'Devansh Parekh', 'Surat, Gujarat', 'Tried these out of curiosity and was blown away! They are delicate, toasted to perfection, and have that unmistakable hill-station bakery aroma. Great as a tea-time nibble or dessert garnish.', 6, NOW(3)),
('salt-biscuit', '5', 'Murali Mohan', 'Tirunelveli, Tamil Nadu', 'These Salt Biscuits are pure perfection—crisp, light, and seasoned with just the right touch of salt. They balance out a sweet cup of masala chai like nothing else. Easily the most comforting snack in our pantry.', 1, NOW(3)),
('salt-biscuit', '4.6', 'Pallavi Deshpande', 'Thane, Maharashtra', 'Not too salty, not overly buttery—just a clean, classic bakery flavor that never gets old. They have a lovely flaky snap when you bite into them and don''t feel heavy at all. Great for daily tea time.', 2, NOW(3)),
('salt-biscuit', '4.4', 'Kiranmai Rao', 'Krishna, Andhra Pradesh', 'I usually avoid sweet biscuits, so these are an absolute lifesaver for my morning coffee routine. Freshly baked with a delicate crunch that melts smoothly in your mouth. Tastes just like childhood bakery visits.', 3, NOW(3)),
('salt-biscuit', '4.8', 'Suresh Babu', 'Kannur, Kerala', 'The texture is spot on—firm enough to hold up when dipped in hot tea, yet light enough to crumble effortlessly. Our elders at home love how gentle and crisp these are compared to hard commercial crackers.', 4, NOW(3)),
('salt-biscuit', '4.5', 'Aditi Kulkarni', 'Dharwad, Karnataka', 'Simple, honest, and super fresh! You can taste the quality of the bake in every bite, with a subtle savory note that keeps you reaching for another. Arrived well-packed with zero breakage.', 5, NOW(3)),
('salt-biscuit', '4', 'Rajeshwar Singh', 'Patna, Bihar', 'An all-time favorite for evening snacks. Whether you eat them plain, with a slice of cheese, or dunked into hot ginger tea, the crispness and balanced saltiness hit the mark every single time.', 6, NOW(3)),
('sweet-biscuit', '4.9', 'Gayathri Balaji', 'Thanjavur, Tamil Nadu', 'These Sweet Biscuits have that warm, nostalgic South Indian bakery charm! They are mildly sweet—never overpowering—with a crisp, melt-in-your-mouth texture that pairs wonderfully with milk or tea.', 1, NOW(3)),
('sweet-biscuit', '4.7', 'Sameer Merchant', 'South Goa, Goa', 'Fresh, golden, and baked just right! Unlike mass-produced biscuits that taste overly sugary or artificial, these have a homemade richness and a clean, comforting crunch. My kids finish a pack in no time.', 2, NOW(3)),
('sweet-biscuit', '4.3', 'Bhavana Prasad', 'Shivamogga, Karnataka', 'Such a delightful treat for sweet-tooth cravings without feeling heavy. Each biscuit has a lovely crisp edge and a soft, crumbly bite that goes brilliantly with strong filter coffee. Always arrives smelling fresh out of the oven.', 3, NOW(3)),
('sweet-biscuit', '5', 'Prashanth Nair', 'Alappuzha, Kerala', 'Reminds me of picking up warm paper bags of biscuits from our neighborhood bakery! The sweetness is gentle and well-balanced, making it easy to enjoy two or three pieces with your evening chai.', 4, NOW(3)),
('sweet-biscuit', '4.5', 'Smriti Banerjee', 'Howrah, West Bengal', 'Light, crunchy, and deliciously simple. They hold together nicely when dipped in warm milk without turning mushy right away. A must-have jar staple for anyone who loves classic bakery biscuits.', 5, NOW(3)),
('sweet-biscuit', '4.8', 'Tarun Bhatia', 'Dehradun, Uttarakhand', 'Really impressed by the freshness and texture. Every biscuit is evenly baked to a golden crunch with just enough sweetness to keep you coming back for one more. Great quality and neat packaging.', 6, NOW(3)),
('trial-combo', '5', 'Rhea Menon', 'Ernakulam, Kerala', 'The Trial Combo is hands down the smartest way to explore their menu! Having smaller portions of multiple varieties helped us find our exact favorites before placing a bulk order. Every single pack arrived super fresh, crisp, and intact.', 1, NOW(3)),
('trial-combo', '4.7', 'Amitabh Kulkarni', 'Pune, Maharashtra', 'I wasn''t sure whether to pick the classic, crispy, or mini variants, so this combo solved my dilemma immediately. Each pouch had that authentic, flaky Ooty bakery crunch without any oiliness. Great value for first-time buyers!', 2, NOW(3)),
('trial-combo', '4.5', 'Sruthi Narayanan', 'Coimbatore, Tamil Nadu', 'Ordered this sampler just to test the quality and packaging for shipping, and I am thoroughly impressed. Not a single piece was crushed, and every variety tasted freshly baked out of the oven. Already planning my next full-size order.', 3, NOW(3)),
('trial-combo', '4.8', 'Karanveer Gill', 'Ludhiana, Punjab', 'Introduced my entire family to authentic Nilgiri snacks through this Trial Combo! Everyone got to pick their favorite style, and the balance of subtle sweetness and crisp layers won everyone over. Will definitely reorder.', 4, NOW(3)),
('trial-combo', '4.4', 'Nivedita Rao', 'Bengaluru Urban, Karnataka', 'Love that you don''t have to commit to one giant pack right away. The portion sizes in the Trial Combo are generous enough for a few evening tea sessions, and the freshness across all packets was top-notch.', 5, NOW(3)),
('trial-combo', '4.9', 'Subhashree Mohanty', 'Cuttack, Odisha', 'Such a well-curated tasting box! From the light, airy flakes to the traditional crunchy layers, every item in the combo felt distinct and homemade. Perfect if you''re trying the brand for the very first time.', 6, NOW(3)),
('tea-time-combo', '5', 'Venkatesh Iyer', 'Chennai, Tamil Nadu', 'Our 5 PM chai ritual has officially been upgraded! The Tea Time Combo gives us a wonderful mix of sweet, savory, and flaky bites so we never get bored. Everything stays crisp and holds up brilliantly when dipped in hot tea.', 1, NOW(3)),
('tea-time-combo', '4.8', 'Ankita Deshpande', 'Nagpur, Maharashtra', 'We keep all the packs from this combo in glass jars on our dining table, and they''re the first thing everyone reaches for with their evening coffee. Light, crunchy, and never overly sweet—just pure comfort.', 2, NOW(3)),
('tea-time-combo', '4.6', 'Jayanth Shenoy', 'Dakshina Kannada, Karnataka', 'Having both salt biscuits and classic Varkey together in one bundle is a game changer. You get that ideal sweet-and-salty balance to pair with strong masala chai or filter coffee. Freshly baked and neatly packed.', 3, NOW(3)),
('tea-time-combo', '4.9', 'Meenakshi Sundaram', 'Madurai, Tamil Nadu', 'This combo is an absolute lifesaver when guests drop by unexpectedly for tea! You can serve a whole platter of authentic bakery treats straight out of the box without any prep. Everyone always asks where we bought them.', 4, NOW(3)),
('tea-time-combo', '4.3', 'Rishabh Jain', 'Jaipur, Rajasthan', 'Really impressed by the variety and shelf life of the Tea Time Combo. Even two weeks after opening, the biscuits retained their snappy crunch in airtight containers. Great everyday snacking value.', 5, NOW(3)),
('tea-time-combo', '4.7', 'Fathima Abdul', 'Kozhikode, Kerala', 'Takes me straight back to rainy evenings in the hills with a steaming cup of tea! Every item in the bundle feels light on the stomach yet deeply satisfying. Hands down our favorite recurring order.', 6, NOW(3)),
('family-combo', '5', 'Pradeep Nair', 'Thiruvananthapuram, Kerala', 'With three generations living under one roof, the Family Combo keeps everyone happy! My parents love the traditional classic Varkey with their morning tea, while the kids finish the mini ones in no time. Huge value for money.', 1, NOW(3)),
('family-combo', '4.8', 'Sunita Agarwal', 'Lucknow, Uttar Pradesh', 'Ordered this large bundle before a weekend family get-together, and it was a massive hit! The quantity is super generous, and every single packet arrived unbroken thanks to the sturdy packaging. Nothing went to waste.', 2, NOW(3)),
('family-combo', '4.7', 'Suresh Babu', 'Salem, Tamil Nadu', 'Instead of buying separate packs every week, this Family Combo stocks up our pantry for the entire month. The quality across all varieties is consistently fresh, golden-baked, and completely free of any greasy aftertaste.', 3, NOW(3)),
('family-combo', '4.5', 'Madhavi Kulkarni', 'Thane, Maharashtra', 'A must-buy for households that take their tea-time snacks seriously! Having multiple flavors and textures in one box means there''s something for every mood, whether you want a light nibble or a hearty dunking biscuit.', 4, NOW(3)),
('family-combo', '4.9', 'Harsha Vardhan', 'Visakhapatnam, Andhra Pradesh', 'Sent the Family Combo to my parents'' house as a surprise, and they couldn''t stop raving about the freshness! The packs are easy to store, and the authentic Ooty bakery taste won over the entire household.', 5, NOW(3)),
('family-combo', '4.4', 'Nandita Chatterjee', 'North 24 Parganas, West Bengal', 'Great savings compared to buying individual packs, and the assortment is thoughtfully put together. From elders who prefer gentle, crisp biscuits to youngsters who love crunchy flakes, everyone found a favorite.', 6, NOW(3)),
('ooty-duo-combo', '5', 'Karthikeyan Raj', 'The Nilgiris, Tamil Nadu', 'The Ooty Duo Combo is pure perfection in a box! Pairing two iconic favorites together gives you the best of both worlds—unbeatable crunch and rich, flaky layers. It tastes just like walking out of a local Ooty bakery.', 1, NOW(3)),
('ooty-duo-combo', '4.8', 'Shilpa Hegde', 'Mysuru, Karnataka', 'Such a neat, no-fuss combo for couples or small households! Two full packs are just the right amount to enjoy fresh without worrying about leftovers going stale. Both varieties paired wonderfully with our morning filter coffee.', 2, NOW(3)),
('ooty-duo-combo', '4.6', 'Siddharth Verma', 'Gurugram, Haryana', 'Bought the Ooty Duo Combo to gift a colleague who misses South Indian bakery snacks, and he loved it! The presentation is clean, the aroma when you open the pouch is amazing, and the crunch is spot on.', 3, NOW(3)),
('ooty-duo-combo', '4.9', 'Divya Menon', 'Thrissur, Kerala', 'If you don''t need a massive family box but still want a little variety for your daily chai breaks, this duo pack is ideal. Both items complement each other brilliantly—light, airy, and baked to golden perfection.', 4, NOW(3)),
('ooty-duo-combo', '4.3', 'Tushar Patil', 'Nashik, Maharashtra', 'Great price point and super fresh batch! I keep one pack at home and take the second one to my office desk for afternoon tea breaks. Both arrived completely intact with zero crumbling.', 5, NOW(3)),
('ooty-duo-combo', '4.7', 'Aparna Krishnan', 'Tiruchirappalli, Tamil Nadu', 'Simple, classic, and deeply satisfying. The Ooty Duo Combo captures the exact nostalgia of hill-station bakeries in two generous packs. We''ve already ordered this twice this month!', 6, NOW(3))
